/* New regression coverage. Existing v091 tests are left intact. */
static void tests_v092(void){
 test_reset();invSelected=47;invDrag=40;invDropConfirm=1;dehydrated=1;itemAnim=3;itemKind=5;new_game();CHECK(invSelected==0&&invDrag==-1&&!invDropConfirm&&!dehydrated&&!itemAnim,"new game clears transient inventory, dehydration and animation state");
 CHECK(!consume_begin(1)&&!consume_begin(2)&&!consume_begin(3)&&!consume_begin(4)&&!consume_begin(5),"consumption rejects every missing item even through direct entry point");
 test_reset();screen=3;uiBuiltScreen=1;uiMouseX=660;uiMouseY=152;pressed[1]=1;tick(.016f);pressed[1]=0;CHECK(job_accepted(0),"first job-board click works even before its first rendered frame");g.money=112;CHECK(load_game()&&job_accepted(0)&&g.money==650,"acceptance is saved immediately, not only at exit");
 test_reset();int rep=g.reputation;for(int j=0;j<NJ;j++)g.jobs[j].deadline=g.absolute-.1f;simulate(1.f/30);CHECK(g.reputation==rep,"expired unaccepted advertisements never damage reputation");
 accept_job(1);g.jobs[1].deadline=g.absolute-.1f;simulate(1.f/30);CHECK(g.reputation==rep-2&&!job_accepted(1)&&navHouse==-1,"only an accepted expired job has a penalty and clears stale route");
 test_reset();g.absolute=80;g.nextBill=30;g.utilities=0;household_bills();CHECK(g.utilities==840&&g.nextBill==102,"calendar catches every crossed bill rather than dropping bills");household_bills();CHECK(g.utilities==840,"same calendar date cannot bill twice");
 test_reset();g.apprentices=1;g.apprenticeXP[0]=25;g.autoWork[0]=1;g.apprenticeTimer[0]=300;simulate(1.f/30);CHECK(g.salary>0&&g.autoWork[0],"apprentice unlock threshold of exactly 25 XP is consistent with completion");
 test_reset();accept_job(0);int house=g.jobs[0].house,pay=g.jobs[0].pay;g.apprentices=3;for(int a=0;a<3;a++){g.apprenticeXP[a]=100;g.apprenticeTimer[a]=300;g.autoWork[a]=1;}simulate(1.f/30);CHECK(job_accepted(0)&&g.jobs[0].house==house&&g.jobs[0].pay==pay,"all independent apprentices leave the player's accepted assignment untouched");
 test_reset();g.x=hx[1]-3;g.z=hz[1]-3;g.playerY=0;for(int n=0;n<NN;n++){PERSON(n).x=180;PERSON(n).z=100;}aim_at(hx[1]-3,.96f,hz[1]-1.7f);interaction();CHECK(interactKind==5&&interactIndex==1,"wallet theft is reachable by aimed world interaction");int cash=g.money;CHECK(steal_cash(1)&&g.money>cash&&g.lateDiscovery==7&&!g.crimeHeat,"unwitnessed theft credits money with delayed discovery");cash=g.money;CHECK(!steal_cash(1)&&g.money==cash,"wallet cannot be looted twice");CHECK(!steal_cash(0)&&!steal_cash(NH)&&!steal_cash(-1),"theft rejects own home and invalid indices");
 test_reset();g.x=hx[1]-3;g.z=hz[1]-3;g.playerY=3;CHECK(!steal_cash(1),"cannot steal through a floor");g.playerY=0;PERSON(0).x=g.x;PERSON(0).z=g.z;rep=g.reputation;CHECK(steal_cash(1)&&g.crimeHeat==48&&g.reputation==rep-7,"visible theft has immediate consequences");
 test_reset();g.x=hx[1]-3;g.z=hz[1]-3;aim_at(hx[1]-3,.96f,hz[1]-1.7f);pressed[1]=1;tick(.016f);pressed[1]=0;CHECK(screen==16,"mouse world interaction opens explicit theft confirmation");cash=g.money;CHECK(click_action(34,1)&&screen==0&&g.money==cash,"refusing theft does not take money");
 test_reset();g.feed=1;g.petHunger=20;g.x=catX;g.z=catZ-1;screen=15;CHECK(click_action(33,0)&&g.feed==0&&catState==4,"feed button consumes food exactly once and starts eating");g.feed=77;CHECK(load_game()&&g.feed==0&&g.petHunger==65,"pet feeding persists immediately without inventing food after reload");
 test_reset();g.food=1;screen=5;inv_sync();draw_ui();for(int n=0;n<uiCount;n++)if(uiButtons[n].action==20&&uiButtons[n].param==0){uiMouseX=uiButtons[n].x+10;uiMouseY=uiButtons[n].y+10;}pressed[2]=1;tick(.016f);pressed[2]=0;CHECK(invSelected==0&&invDrag==-1&&g.food==1&&!itemAnim,"right mouse selects a stack without consuming it or starting drag");
 test_reset();g.winter=1;g.x=-20;g.z=-9;insideHouse=-1;g.illness=20;g.weather=0;simulate(1);CHECK(g.illness>20,"winter exposure can cause illness");g.x=hx[0];g.z=hz[0];update_interior();float illness=g.illness;simulate(1);CHECK(g.illness<illness,"warm shelter reduces exposure illness");
 test_reset();CHECK(activity_name(8)!=activity_name(0)&&activity_name(11)!=activity_name(0),"social and child schedules expose meaningful activity names");
}
